using CampusPlacementManagement.Data;
using CampusPlacementManagement.DTOs.JobApplications;
using CampusPlacementManagement.Models;
using CampusPlacementManagement.Models.Enums;
using CampusPlacementManagement.Repositories.Interfaces;
using CampusPlacementManagement.Services.Interfaces;
using Microsoft.EntityFrameworkCore;
namespace CampusPlacementManagement.Services;
public class JobApplicationService:IJobApplicationService
{
 private readonly IJobApplicationRepository _repo;private readonly ApplicationDbContext _db;private readonly IEligibilityService _eligibility;
 public JobApplicationService(IJobApplicationRepository repo,ApplicationDbContext db,IEligibilityService eligibility){_repo=repo;_db=db;_eligibility=eligibility;}
 public async Task<JobApplication> ApplyAsync(int jobId,string studentUserId,ApplyJobDto dto){var s=await _db.Students.Include(x=>x.College).FirstOrDefaultAsync(x=>x.UserId==studentUserId)??throw new UnauthorizedAccessException();var job=await _db.Jobs.Include(x=>x.EligibilityCriteria).Include(x=>x.TargetColleges).FirstOrDefaultAsync(x=>x.JobId==jobId)??throw new KeyNotFoundException("Job not found.");if(job.Status!=JobStatus.Published||job.ApplicationDeadline<DateTime.UtcNow)throw new InvalidOperationException("Job is not open for applications.");if(!job.IsOpenToAllColleges&&!job.TargetColleges.Any(x=>x.CollegeId==s.CollegeId))throw new UnauthorizedAccessException("Job is not open to your college.");var e=await _eligibility.EvaluateAsync(job,s);if(!e.Eligible)throw new InvalidOperationException(string.Join(" ",e.Reasons));if(await _repo.GetByStudentAndJobAsync(s.StudentId,jobId)!=null)throw new InvalidOperationException("Duplicate application is not allowed.");var a=new JobApplication{JobId=jobId,StudentId=s.StudentId,ResumeUrl=dto.ResumeUrl,Status=ApplicationStatus.Applied};await _repo.AddAsync(a);await _db.SaveChangesAsync();await AddHistory(a,null,ApplicationStatus.Applied,studentUserId,"Application submitted.");return a;}
 public async Task<List<JobApplication>> GetMyApplicationsAsync(string userId){var s=await _db.Students.FirstOrDefaultAsync(x=>x.UserId==userId)??throw new UnauthorizedAccessException();return await _repo.GetByStudentAsync(s.StudentId);}
 public async Task<JobApplication> GetByIdAsync(int id,string userId){var a=await _repo.GetByIdAsync(id)??throw new KeyNotFoundException("Application not found.");var student=await _db.Students.FirstOrDefaultAsync(x=>x.UserId==userId);var hr=await _db.CompanyHRs.FirstOrDefaultAsync(x=>x.UserId==userId);var officer=await _db.PlacementOfficers.FirstOrDefaultAsync(x=>x.UserId==userId);if(student?.StudentId==a.StudentId)return a;if(hr?.CompanyHRId==a.Job.CreatedByHRId)return a;if(officer!=null&&officer.CollegeId==a.Student.CollegeId)return a;throw new UnauthorizedAccessException();}
 public async Task<List<JobApplication>> GetForJobAsync(int jobId,string userId){var hr=await _db.CompanyHRs.FirstOrDefaultAsync(x=>x.UserId==userId)??throw new UnauthorizedAccessException();if(!await _db.Jobs.AnyAsync(x=>x.JobId==jobId&&x.CreatedByHRId==hr.CompanyHRId))throw new UnauthorizedAccessException();return await _repo.GetByJobAsync(jobId);}
 public Task ShortlistAsync(int id,string userId,string? remarks)=>ChangeStatus(id,userId,ApplicationStatus.Shortlisted,remarks,true);public Task RejectAsync(int id,string userId,string? remarks)=>ChangeStatus(id,userId,ApplicationStatus.Rejected,remarks,true);public Task WithdrawAsync(int id,string userId,string? remarks)=>ChangeStatus(id,userId,ApplicationStatus.Withdrawn,remarks,false);
 private async Task ChangeStatus(int id,string userId,ApplicationStatus status,string? remarks,bool hrOnly){var a=await _repo.GetByIdAsync(id)??throw new KeyNotFoundException("Application not found.");var hr=await _db.CompanyHRs.FirstOrDefaultAsync(x=>x.UserId==userId);var student=await _db.Students.FirstOrDefaultAsync(x=>x.UserId==userId);if(hrOnly){if(hr==null||hr.CompanyHRId!=a.Job.CreatedByHRId)throw new UnauthorizedAccessException();}else if(student==null||student.StudentId!=a.StudentId)throw new UnauthorizedAccessException();var previous=a.Status;a.Status=status;a.LastUpdatedAt=DateTime.UtcNow;_repo.Update(a);await _repo.SaveChangesAsync();await AddHistory(a,previous,status,userId,remarks);}
 private async Task AddHistory(JobApplication a,ApplicationStatus? previous,ApplicationStatus next,string userId,string? remarks){await _db.ApplicationStatusHistories.AddAsync(new ApplicationStatusHistory{ApplicationId=a.ApplicationId,PreviousStatus=previous,NewStatus=next,UpdatedByUserId=userId,Remarks=remarks});await _db.SaveChangesAsync();}
}
